:root {
  --color-bg: #0b1020;
  --color-surface: #141a2e;
  --color-text: #e6e9f2;
  --color-muted: #9aa3bd;
  --color-border: #273150;
  --color-focus: #4ade80;
  --color-danger: #f87171;

  --radius: 12px;
  --space: 16px;
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
