1	#!/usr/bin/env node
2	/**
3	 * Keep one committed API Extractor report per public module entry.
4	 *
5	 * The entries come from the workspace packages (`apps/*`, `packages/*`,
6	 * `showcase/<id>/*`). A package's own entry, the `types` or default condition of
7	 * `exports["."]` in its `package.json`, gives `<package>/etc/<unscoped name>.api.md`
8	 * (`apps/api/etc/api.api.md` for `@repo/api`). Inside a package, each
9	 * `src/routes/<name>/index.ts` and `src/features/<name>/index.ts` gives
10	 * `<package>/etc/<folder>-<name>.api.md`, and `src/api-client/index.ts` gives
11	 * `<package>/etc/api-client.api.md`.
12	 *
13	 * `node scripts/api-report.mjs --local` (`pnpm api:report`) rewrites the
14	 * reports. Without `--local` (`pnpm api:check`) it compares and exits 1 when any
15	 * committed report differs from the code.
16	 */
17	
18	import { execFileSync } from 'node:child_process';
19	import { existsSync, mkdirSync, readdirSync, readFileSync, realpathSync, rmSync } from 'node:fs';
20	import { dirname, join, posix, resolve } from 'node:path';
21	import { fileURLToPath, pathToFileURL } from 'node:url';
22	import { Extractor, ExtractorConfig } from '@microsoft/api-extractor';
23	
24	const REPOSITORY_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
25	const CACHE_DIRECTORY = join(REPOSITORY_ROOT, '.cache/api');
26	const DECLARATIONS_DIRECTORY = join(REPOSITORY_ROOT, '.cache/types');
27	
28	const PACKAGE_MANIFEST = /^(apps\/[^/]+|packages\/[^/]+|showcase\/[^/]+\/[^/]+)\/package\.json$/;
29	const MODULE_ENTRY = /^src\/(?:(routes|features)\/([^/]+)|(api-client))\/index\.ts$/;
30	
31	/** The file `exports["."]` names for types, or by default. */
32	function packageEntry(exports) {
33	  const root =
34	    typeof exports === 'object' && exports !== null ? (exports['.'] ?? exports) : exports;
35	  const entry = typeof root === 'string' ? root : (root?.types ?? root?.default);
36	  return typeof entry === 'string' ? posix.normalize(entry) : undefined;
37	}
38	
39	/**
40	 * List `{ name, entry, packageRoot }` for every public entry among `files`. Pure.
41	 *
42	 * @param {string[]} files repository-relative paths: package manifests and sources
43	 * @param {(path: string) => { name: string, exports?: unknown }} readManifest
44	 */
45	export function listPublicEntries(files, readManifest) {
46	  const packageRoots = files
47	    .filter((file) => PACKAGE_MANIFEST.test(file))
48	    .map((file) => posix.dirname(file))
49	    .sort();
50	  return packageRoots.flatMap((packageRoot) => {
51	    const manifest = readManifest(`${packageRoot}/package.json`);
52	    const ownEntry = packageEntry(manifest.exports);
53	    const modules = files
54	      .filter((file) => file.startsWith(`${packageRoot}/`))
