#!/usr/bin/env node
/**
 * Keep one committed API Extractor report per public module entry.
 *
 * The entries come from the workspace packages (`apps/*`, `packages/*`,
 * `showcase/<id>/*`). A package's own entry, the `types` or default condition of
 * `exports["."]` in its `package.json`, gives `<package>/etc/<unscoped name>.api.md`
 * (`apps/api/etc/api.api.md` for `@repo/api`). Inside a package, each
 * `src/routes/<name>/index.ts` and `src/features/<name>/index.ts` gives
 * `<package>/etc/<folder>-<name>.api.md`, and `src/api-client/index.ts` gives
 * `<package>/etc/api-client.api.md`.
 *
 * `node scripts/api-report.mjs --local` (`pnpm api:report`) rewrites the
 * reports. Without `--local` (`pnpm api:check`) it compares and exits 1 when any
 * committed report differs from the code.
 */

import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, readdirSync, readFileSync, realpathSync, rmSync } from 'node:fs';
import { dirname, join, posix, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { Extractor, ExtractorConfig } from '@microsoft/api-extractor';

const REPOSITORY_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const CACHE_DIRECTORY = join(REPOSITORY_ROOT, '.cache/api');
const DECLARATIONS_DIRECTORY = join(REPOSITORY_ROOT, '.cache/types');

const PACKAGE_MANIFEST = /^(apps\/[^/]+|packages\/[^/]+|showcase\/[^/]+\/[^/]+)\/package\.json$/;
const MODULE_ENTRY = /^src\/(?:(routes|features)\/([^/]+)|(api-client))\/index\.ts$/;

/** The file `exports["."]` names for types, or by default. */
function packageEntry(exports) {
  const root =
    typeof exports === 'object' && exports !== null ? (exports['.'] ?? exports) : exports;
  const entry = typeof root === 'string' ? root : (root?.types ?? root?.default);
  return typeof entry === 'string' ? posix.normalize(entry) : undefined;
}

/**
 * List `{ name, entry, packageRoot }` for every public entry among `files`. Pure.
 *
 * @param {string[]} files repository-relative paths: package manifests and sources
 * @param {(path: string) => { name: string, exports?: unknown }} readManifest
 */
export function listPublicEntries(files, readManifest) {
  const packageRoots = files
    .filter((file) => PACKAGE_MANIFEST.test(file))
    .map((file) => posix.dirname(file))
    .sort();
  return packageRoots.flatMap((packageRoot) => {
    const manifest = readManifest(`${packageRoot}/package.json`);
    const ownEntry = packageEntry(manifest.exports);
    const modules = files
      .filter((file) => file.startsWith(`${packageRoot}/`))
      .map((file) => ({ file, match: MODULE_ENTRY.exec(file.slice(packageRoot.length + 1)) }))
      .filter(({ match }) => match)
      .map(({ file, match: [, folder, module, apiClient] }) => ({
        name: apiClient ?? `${folder}-${module}`,
        entry: file,
        packageRoot,
      }))
      .sort((left, right) => left.name.localeCompare(right.name));
    const own = ownEntry
      ? [
          {
            name: manifest.name.replace(/^@[^/]+\//, ''),
            entry: posix.join(packageRoot, ownEntry),
            packageRoot,
          },
        ]
      : [];
    return [...own, ...modules];
  });
}

/** Package manifests and candidate module entries on disk, repository-relative. */
function workspaceFiles() {
  const directories = (path) =>
    existsSync(join(REPOSITORY_ROOT, path))
      ? readdirSync(join(REPOSITORY_ROOT, path), { withFileTypes: true })
          .filter((entry) => entry.isDirectory())
          .map((entry) => `${path}/${entry.name}`)
      : [];
  const packageRoots = [
    ...directories('apps'),
    ...directories('packages'),
    ...directories('showcase').flatMap(directories),
  ].filter((root) => existsSync(join(REPOSITORY_ROOT, root, 'package.json')));
  return packageRoots
    .flatMap((root) => [
      `${root}/package.json`,
      `${root}/src/api-client/index.ts`,
      ...['routes', 'features'].flatMap((folder) =>
        directories(`${root}/src/${folder}`).map((module) => `${module}/index.ts`),
      ),
    ])
    .filter((file) => existsSync(join(REPOSITORY_ROOT, file)));
}

/**
 * The api program is composite and writes its declarations to `.cache/types`,
 * where the browser program reads the api contract; the web declarations join them.
 */
function emitDeclarations() {
  rmSync(DECLARATIONS_DIRECTORY, { recursive: true, force: true });
  const tsc = join(REPOSITORY_ROOT, 'node_modules/.bin/tsc');
  const options = { cwd: REPOSITORY_ROOT, stdio: 'inherit' };
  execFileSync(tsc, ['-p', 'tsconfig.api.json'], options);
  execFileSync(
    tsc,
    [
      ...['-p', 'tsconfig.json', '--noEmit', 'false', '--declaration', '--emitDeclarationOnly'],
      ...['--rootDir', REPOSITORY_ROOT, '--outDir', DECLARATIONS_DIRECTORY],
    ],
    options,
  );
}

function runExtractor({ name: reportName, entry, packageRoot }, localBuild) {
  const reportDirectory = join(packageRoot, 'etc');
  mkdirSync(join(REPOSITORY_ROOT, reportDirectory), { recursive: true });
  const configObject = {
    projectFolder: REPOSITORY_ROOT,
    mainEntryPointFilePath: join(DECLARATIONS_DIRECTORY, entry.replace(/\.ts$/, '.d.ts')),
    compiler: {
      overrideTsconfig: {
        compilerOptions: {
          target: 'ES2022',
          lib: ['ES2022', 'DOM', 'DOM.Iterable'],
          module: 'ESNext',
          moduleResolution: 'Bundler',
          jsx: 'react-jsx',
          // The api's declarations keep their explicit `.ts` import extensions.
          allowImportingTsExtensions: true,
          noEmit: true,
          strict: true,
          skipLibCheck: true,
          types: [],
        },
        include: [DECLARATIONS_DIRECTORY],
      },
    },
    apiReport: {
      enabled: true,
      reportFileName: reportName,
      reportFolder: join(REPOSITORY_ROOT, reportDirectory),
      reportTempFolder: join(CACHE_DIRECTORY, 'temp'),
    },
    docModel: { enabled: false },
    dtsRollup: { enabled: false },
    tsdocMetadata: { enabled: false },
    messages: {
      extractorMessageReporting: {
        // The repo has no release stages, so the @public/@beta tags carry no meaning.
        'ae-missing-release-tag': { logLevel: 'none' },
      },
    },
  };
  const config = ExtractorConfig.prepare({
    configObject,
    configObjectFullPath: undefined,
    packageJsonFullPath: join(REPOSITORY_ROOT, packageRoot, 'package.json'),
    packageJson: { name: reportName, version: '0.0.0' },
  });
  const result = Extractor.invoke(config, { localBuild });
  if (result.apiReportChanged && !localBuild) {
    console.error(
      `api: ${entry} differs from ${reportDirectory}/${reportName}.api.md. Run \`pnpm api:report\` and commit the report.`,
    );
  }
  return result.succeeded;
}

function runCli() {
  const localBuild = process.argv.includes('--local');
  const entries = listPublicEntries(workspaceFiles(), (path) =>
    JSON.parse(readFileSync(join(REPOSITORY_ROOT, path), 'utf8')),
  );
  if (entries.length === 0) {
    console.error('api: the workspace packages list no public module entries.');
    process.exit(1);
  }
  emitDeclarations();
  const failed = entries.filter((entry) => !runExtractor(entry, localBuild));
  process.exit(failed.length === 0 ? 0 : 1);
}

if (process.argv[1] && import.meta.url === pathToFileURL(realpathSync(process.argv[1])).href) {
  runCli();
}

{
  // size-limit auto-loads its plugins (the @size-limit/* packages) from
  // package.json at runtime, so @size-limit/file is never `import`ed in source.
  // It is genuinely used by the `size` script — tell Fallow so the dependency
  // audit stays honest rather than flagging a false positive on every run.
  "ignoreDependencies": ["@size-limit/file"],

  // jest.style-stub.cjs is referenced as a string in jest.config.ts
  // (moduleNameMapper), not imported, so it isn't statically reachable. It is
  // used by every test run — exclude it from dead-file analysis.
  "ignorePatterns": ["jest.style-stub.cjs", "vendor/**"],

  // The contract's banned imports and calls per role (ADR 0032).
  "rulePacks": ["tooling/architecture/contract.rules.jsonc"],

  // `fallow audit` fails on every finding in the files a change touches, not
  // only the ones it introduces. That needs no base-revision pass, which reads
  // the base tree with this config and fails when the base predates a file the
  // config names, such as the rule pack above.
  "audit": { "gate": "all" },

  "rules": {
    // A rule-pack finding fails the gate, like a boundary violation.
    "policy-violation": "error",
    // Every fallow-ignore comment names its reason.
    "require-suppression-reason": "error"
  },

  // Architecture boundaries enforce the role table in
  // .agents/project/ARCHITECTURE.md (ADR 0032). Each role is a zone whose
  // patterns match every result by brace glob: the reference in `apps/` and
  // each `showcase/<id>/`. The reference web app also keeps one child zone per
  // route folder (autoDiscover), so a route that imports another route fails
  // here as well as in ESLint `policy/slice-isolation`, which owns sibling
  // isolation for every result; that rule also keeps one feature from importing
  // another. Web features are a single zone — a web feature, unlike a route,
  // is optional, so the zone has one member only when a result adds one.
  // The routes and features patterns name only files inside
  // a slice folder, so a loose file directly under `routes/` or `features/`
  // sits in no zone and `coverage.requireAllFiles` fails it. The patterns also
  // keep the config valid on a tree where those folders are missing, such as
  // the base revision `fallow audit` reads.
  // The rules below make Fallow FAIL (boundary-violation defaults to error) on
  // any value import they do not allow. This file is also the source for the role
  // diagram (pnpm arch:diagram).
  "boundaries": {
    "zones": [
      {
        "name": "web-app",
        "patterns": [
          "{apps,showcase/*}/web/src/main.tsx",
          "{apps,showcase/*}/web/src/App.tsx",
          "{apps,showcase/*}/web/src/index.css"
        ]
      },
      { "name": "web-api-client", "patterns": ["{apps,showcase/*}/web/src/api-client/**"] },
      {
        "name": "web-routes",
        "autoDiscover": ["apps/web/src/routes"],
        "patterns": ["{apps,showcase/*}/web/src/routes/*/**"]
      },
      {
        "name": "web-features",
        "patterns": ["{apps,showcase/*}/web/src/features/*/**"]
      },
      { "name": "ui", "patterns": ["packages/ui/src/**"] },
      {
        "name": "api-app",
        "patterns": ["{apps,showcase/*}/api/src/server.ts", "{apps,showcase/*}/api/src/router.ts"]
      },
      { "name": "api-trpc", "patterns": ["{apps,showcase/*}/api/src/trpc.ts"] },
      {
        "name": "api-procedures",
        "patterns": [
          "{apps,showcase/*}/api/src/features/*/{index,procedures}.ts",
          "{apps,showcase/*}/api/src/features/*/procedures/**"
        ]
      },
      {
        "name": "api-application",
        "patterns": [
          "{apps,showcase/*}/api/src/features/*/application.ts",
          "{apps,showcase/*}/api/src/features/*/application/**"
        ]
      },
      {
        "name": "api-domain",
        "patterns": [
          "{apps,showcase/*}/api/src/features/*/domain.ts",
          "{apps,showcase/*}/api/src/features/*/domain/**"
        ]
      },
      {
        "name": "api-integrations",
        "patterns": [
          "{apps,showcase/*}/api/src/features/*/integrations.ts",
          "{apps,showcase/*}/api/src/features/*/integrations/**"
        ]
      }
    ],
    // `allow` lists the roles a role may import by value. `allowTypeOnly` lists
    // every other role, so a type-only import (`import type`, `export type ...
    // from`) between any two roles passes (ADR 0037). A role is never listed
    // for itself: sibling slices stay isolated for types too.
    "rules": [
      // The composition root mounts the routes inside the api providers.
      {
        "from": "web-app",
        "allow": ["web-routes", "web-api-client", "ui"],
        "allowTypeOnly": [
          "web-features",
          "api-app",
          "api-trpc",
          "api-procedures",
          "api-application",
          "api-domain",
          "api-integrations"
        ]
      },
      // The api client wires the tRPC client over the router type; it imports
      // no other role by value.
      {
        "from": "web-api-client",
        "allow": [],
        "allowTypeOnly": [
          "web-app",
          "web-routes",
          "web-features",
          "ui",
          "api-app",
          "api-trpc",
          "api-procedures",
          "api-application",
          "api-domain",
          "api-integrations"
        ]
      },
      // A route composes a page from features, the api client and the ui kit.
      // Each route folder is its own child zone, so a route never imports
      // another route, not even a type.
      {
        "from": "web-routes",
        "allow": ["web-features", "web-api-client", "ui"],
        "allowTypeOnly": [
          "web-app",
          "api-app",
          "api-trpc",
          "api-procedures",
          "api-application",
          "api-domain",
          "api-integrations"
        ]
      },
      // A feature is shared web code that routes compose; one feature never
      // imports another, not even a type.
      {
        "from": "web-features",
        "allow": ["web-api-client", "ui"],
        "allowTypeOnly": [
          "web-app",
          "web-routes",
          "api-app",
          "api-trpc",
          "api-procedures",
          "api-application",
          "api-domain",
          "api-integrations"
        ]
      },
      // UI primitives import no other role by value.
      {
        "from": "ui",
        "allow": [],
        "allowTypeOnly": [
          "web-app",
          "web-api-client",
          "web-routes",
          "web-features",
          "api-app",
          "api-trpc",
          "api-procedures",
          "api-application",
          "api-domain",
          "api-integrations"
        ]
      },
      // The api composition root mounts the feature routers on the tRPC base.
      {
        "from": "api-app",
        "allow": ["api-trpc", "api-procedures"],
        "allowTypeOnly": [
          "web-app",
          "web-api-client",
          "web-routes",
          "web-features",
          "ui",
          "api-application",
          "api-domain",
          "api-integrations"
        ]
      },
      {
        "from": "api-trpc",
        "allow": [],
        "allowTypeOnly": [
          "web-app",
          "web-api-client",
          "web-routes",
          "web-features",
          "ui",
          "api-app",
          "api-procedures",
          "api-application",
          "api-domain",
          "api-integrations"
        ]
      },
      // Procedures validate input and delegate to application logic; they may
      // name domain types, never call domain code.
      {
        "from": "api-procedures",
        "allow": ["api-trpc", "api-application"],
        "allowTypeOnly": [
          "web-app",
          "web-api-client",
          "web-routes",
          "web-features",
          "ui",
          "api-app",
          "api-domain",
          "api-integrations"
        ]
      },
      {
        "from": "api-application",
        "allow": ["api-domain", "api-integrations"],
        "allowTypeOnly": [
          "web-app",
          "web-api-client",
          "web-routes",
          "web-features",
          "ui",
          "api-app",
          "api-trpc",
          "api-procedures"
        ]
      },
      // The domain is pure: it imports no other role by value.
      {
        "from": "api-domain",
        "allow": [],
        "allowTypeOnly": [
          "web-app",
          "web-api-client",
          "web-routes",
          "web-features",
          "ui",
          "api-app",
          "api-trpc",
          "api-procedures",
          "api-application",
          "api-integrations"
        ]
      },
      {
        "from": "api-integrations",
        "allow": ["api-domain"],
        "allowTypeOnly": [
          "web-app",
          "web-api-client",
          "web-routes",
          "web-features",
          "ui",
          "api-app",
          "api-trpc",
          "api-procedures",
          "api-application"
        ]
      }
    ],
    "coverage": {
      // Every source file belongs to a role; no extra layers.
      "requireAllFiles": true,
      "allowUnmatched": [
        "**/*.test.{ts,tsx}",
        "**/*.d.ts",
        "**/*.d.mts",
        "{commitlint,jest,playwright}.config.ts",
        "jest.setup.ts",
        "jest.style-stub.cjs",
        "eslint.config.js",
        "team-walkthrough.html",
        "{apps,showcase/*}/web/{index.html,vite.config.ts}",
        "{apps,showcase/*}/web/e2e/**",
        ".claude/**",
        "scripts/**",
        "tooling/**",
        "vendor/**"
      ]
    }
  }
}

