680	const procedureInputSchema = {
681	  meta: {
682	    type: 'problem',
683	    messages: {
684	      schema:
685	        'Pass the procedure input as `Schema.toStandardSchemaV1(<schema>)` with `Schema` from ' +
686	        '`effect`, so the procedure validates its input with Effect Schema (ADR 0011).',
687	    },
688	    schema: [],
689	  },
690	  create(context) {
691	    if (!API_SOURCE.test(repositoryPath(context)) || isTestFile(context.filename)) {
692	      return {};
693	    }
694	    const standardSchema = effectStandardSchema();
695	    return {
696	      ImportDeclaration: standardSchema.ImportDeclaration,
697	      CallExpression(node) {
698	        const { callee } = node;
699	        if (
700	          callee.type === 'MemberExpression' &&
701	          (callee.computed ? callee.property.value : callee.property.name) === 'input' &&
702	          !standardSchema.wraps(node.arguments[0])
703	        ) {
704	          context.report({ node, messageId: 'schema' });
705	        }
706	      },
707	    };
708	  },
709	};
