711	const formUsesEffectSchema = {
712	  meta: {
713	    type: 'problem',
714	    messages: {
715	      resolver:
716	        'Pass `useForm({ resolver: standardSchemaResolver(Schema.toStandardSchemaV1(<schema>)) })` ' +
717	        'with `standardSchemaResolver` from `@hookform/resolvers/standard-schema` and `Schema` ' +
718	        'from `effect`, so the form validates with Effect Schema (ADR 0011). Pass the schema ' +
719	        'as the only argument, so the form submits the decoded value, and write the options ' +
720	        'inline, with no spread that could replace the resolver.',
