#!/usr/bin/env node
/**
 * Each PRD in `docs/prd/` states a feature's intent, and each behaviour it
 * lists names the E2E test that proves it (ADR 0045). The specs stay the
 * contract (ADR 0003), so this check fails on a conflict between the two: a PRD
 * with no behaviours, a behaviour that names no test, a line under
 * `## Behaviours` it cannot read, or a `Proved by` link to a spec file or test
 * title that does not exist.
 *
 * A behaviour is a top-level `- ` item under `## Behaviours`. Its proofs are
 * nested items of the form `- Proved by [<test title>](<path to the spec>)`,
 * with the path relative to the PRD and any `#` anchor ignored. A test counts
 * when its spec is a tracked `web/e2e/**\/*.spec.ts` file and a
 * `test('<title>', ...)` call in it has that exact literal title and runs: the
 * spec is parsed, so a test in a comment, a `test.skip`, `test.fixme` or
 * `test.fail`, a test inside `test.describe.skip` or `test.describe.fixme`, a
 * test or group whose `annotation` details have the type `skip`, `fixme` or
 * `fail`, and a test in a test, group or file that calls `test.skip(...)`,
 * `test.fixme(...)` or `test.fail(...)` without a test body, or
 * `testInfo.skip(...)`, `testInfo.fixme(...)` or `testInfo.fail(...)`, prove
 * nothing. A `test.fail` test passes only while its assertions fail.
 */

import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync, realpathSync } from 'node:fs';
import { matchesGlob, posix, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import ts from 'typescript';

const PRD_GLOB = 'docs/prd/*.md';
const SPEC_GLOB = '**/web/e2e/**/*.spec.ts';
const BEHAVIOURS_HEADING = /^## Behaviours\s*$/;
const BEHAVIOUR = /^[-*] (.*)$/;
const PROOF = /^(?:\t| {2})\s*[-*] Proved by \[(.+)\]\(([^)\s<>]+)\)\s*$/;
const UNREAD_LINE = /^ ?(?:[-*+]|\d+[.)])\s|^\s+(?:(?:[-*+]|\d+[.)])\s+)?Proved by\b/;

/**
 * What each Playwright call declares, by its whole callee. A `test` is a test
 * that runs (`.only` runs too; CI's `forbidOnly` owns the focus rule), and a
 * `group` holds tests.
===handler-names rule===
const handlerNames = {
  meta: {
    type: 'problem',
    messages: {
      prefix:
        'Rename `{{name}}` to `handle{{suffix}}`. Functions defined inside a component start ' +
        'with `handle`; callback props start with `on`.',
    },
    schema: [],
  },
  create(context) {
    return {
      Program(program) {
        for (const { fn } of moduleComponents(program, context.filename)) {
          for (const identifier of localFunctions(fn.body)) {
            if (!/^handle[A-Z]/.test(identifier.name)) {
              const suffix = identifier.name.charAt(0).toUpperCase() + identifier.name.slice(1);
              context.report({
                node: identifier,
                messageId: 'prefix',
                data: { name: identifier.name, suffix },
              });
            }
          }
        }
      },
    };
  },
};
    'handler-names': handlerNames,
    'callback-prop-names': callbackPropNames,
    'pages-in-routes': pagesInRoutes,
    'file-matches-export': fileMatchesExport,
    'folder-names': folderNames,
    'role-named-folders': roleNamedFolders,
    'test-beside-subject': testBesideSubject,
    'slice-isolation': sliceIsolation,
    'procedure-input-schema': procedureInputSchema,
    'form-uses-effect-schema': formUsesEffectSchema,
  },
};

